syntax:
for (initialisation; condition; update) {
    // body: runs once per iteration
}

// count up:      for (int i = 1; i <= 5; i++)
// count down:    for (int i = 5; i >= 1; i--)
// step of 2:     for (int i = 0; i <= 10; i += 2)
// two variables: for (int i = 0, j = 10; i < j; i++, j--)
// note: no semicolon after the closing parenthesis ) of the for

sample.code:
#include <iostream>
using namespace std;

int main() {
    int sum = 0;
    for (int i = 1; i <= 5; i++) {
        cout << i << " ";
        sum += i;
    }
    cout << endl << "Sum = " << sum << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= 10; i++) {
        cout << n << " x " << i << " = " << n * i << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    long long fact = 1;
    for (int i = 1; i <= n; i++) {
        fact *= i;
    }
    cout << n << "! = " << fact << endl;
    return 0;
}

